Method.Source:
    /// <summary>
    /// Initializes states of fields defined on the Reason form extension.
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormEventHandler(formStr(Reasons), FormEventType::Initialized)]
    public static void Reasons_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        ReasonsIForm reasonForm = sender as ReasonsIForm;

        if (reasonForm)
        {
            ReasonFormTable reasonFormTable = reasonForm.getReasonFormTable();

            if (reasonFormTable.parmReasonGridInvoiceMatchingGroup())
            {
                boolean showInvMatchFields = reasonFormTable.parmReasonCodeAccountType() == ReasonCodeAccountTypeAll::Vend ||
                                             reasonFormTable.parmReasonCodeAccountType() == ReasonCodeAccountTypeAll::AllValues;
                reasonFormTable.parmReasonGridInvoiceMatchingGroup().visible(showInvMatchFields);
            }
        }
    }

    /// <summary>
    /// Sets the initial visibility and form caption values based on how the Financial reasons form was called.
    /// </summary>
    /// <param name="_args">The event arguments.</param>
    [PostHandlerFor(classStr(ReasonFormTable), methodStr(ReasonFormTable, initControls))]
    public static void ReasonFormTable_Post_initControls(XppPrePostArgs _args)
    {
        ReasonFormTable thisClass = _args.getThis();
        ReasonCodeAccountTypeAll rcAccountTypeMenu = _args.getArg('_rcAccountTypeMenu');

        switch (rcAccountTypeMenu)
        {
            case ReasonCodeAccountTypeAll::Vend:

                FormControlId invoiceMatchGroup = thisClass.parmReasonFormInstance().controlId(formControlStr(Reasons, METInvoiceMatching));
                if (invoiceMatchGroup)
                {
                    thisClass.parmReasonFormInstance().control(invoiceMatchGroup).visible(true);
                }

                break;
        }
    }
